/**
 * Diff Store - Persists per-file diff records for on-demand retrieval.
 *
 * Each session gets one JSON Lines file at ~/.happy/diffs/{sessionId}.jsonl,
 * one record per line, appended as diffs are generated by DiffProcessors.
 * The App can later fetch a specific record via the getDiffDetail RPC handler.
 */

import { join } from 'node:path';
import { configuration } from '@/configuration';
import { logger } from '@/ui/logger';
import { appendJsonLines, findInJsonArrayFile, findJsonLine } from './jsonlRecordFile';

export interface DiffRecord {
    callId: string;
    agent: 'codex' | 'gemini' | 'claude';
    filePath: string;
    diff: string;
    additions: number;
    deletions: number;
    timestamp: number;
}

const diffsDir = join(configuration.happyHomeDir, 'diffs');

function getFilePath(sessionId: string): string {
    return join(diffsDir, `${sessionId}.jsonl`);
}

// Written by versions that rewrote one JSON array per save; still read, never written
function getLegacyFilePath(sessionId: string): string {
    return join(diffsDir, `${sessionId}.json`);
}

/**
 * Save one or more diff records for a session.
 * Appends them to the session's file without reading it.
 */
export function saveDiffRecords(sessionId: string, records: DiffRecord[]): void {
    if (records.length === 0) return;

    appendJsonLines(getFilePath(sessionId), records).then(
        () => logger.debug(`[DiffStore] Saved ${records.length} record(s) for session ${sessionId}`),
        (error) => logger.warn(`[DiffStore] Failed to save diff records:`, error)
    );
}

/**
 * Get a specific diff record by callId and filePath.
 */
export async function getDiffDetail(
    sessionId: string,
    callId: string,
    filePath: string
): Promise<{ diff: string; additions: number; deletions: number } | null> {
    try {
        const match = (r: DiffRecord) => r.callId === callId && r.filePath === filePath;
        const record = await findJsonLine(getFilePath(sessionId), JSON.stringify(callId), match)
            ?? await findInJsonArrayFile(getLegacyFilePath(sessionId), match);
        if (!record) return null;

        return { diff: record.diff, additions: record.additions, deletions: record.deletions };
    } catch (error) {
        logger.warn(`[DiffStore] Failed to get diff detail:`, error);
        return null;
    }
}
